using System.Windows;using OdinVault.Manager.Wpf.ViewModels;namespace OdinVault.Manager.Wpf.Views;public partial class MobileView:System.Windows.Controls.UserControl{public MobileView(){InitializeComponent();}void Save_Click(object s,RoutedEventArgs e){if(DataContext is MobileViewModel m)try{m.Save();}catch(Exception x){System.Windows.MessageBox.Show(x.Message,"OdinVault");}}async void Agent_Click(object s,RoutedEventArgs e){if(DataContext is MobileViewModel m)await m.TestAgentAsync();}async void Port_Click(object s,RoutedEventArgs e){if(DataContext is MobileViewModel m)await m.TestPortAsync();}}